import AppKit

// MARK: - Progress

/// The sheet that stays up while reversed assets are rendered: a bar, the file
/// being reversed, a Cancel that stops within one slice, and the report when
/// it is over.
///
/// **Why a sheet and not a background job with a badge.** A reversed clip that
/// has not been rendered draws a slate, so the timeline is telling the truth
/// but the picture is missing — and a user who ticked Reverse two seconds ago
/// needs to be told that the missing picture is being made, how far along it
/// is, and how to stop it. The sheet is also what stops the timeline moving
/// under a render: every editor action validates false while one is attached
/// (`EditorViewController.validateUserInterfaceItem`), which is the same
/// bargain Export and Consolidate Media strike.
///
/// It owns the run, so the render survives whatever the editor does next — the
/// presenting controller retains the sheet while it is on screen, and nothing
/// else holds the token.
final class ReverseProgressSheetController: NSViewController {
    /// Weak: the sheet is presented BY this document's editor, so a strong
    /// reference would be a cycle for as long as it is up.
    private weak var document: ProjectDocument?
    private let jobs: [ReverseRenderer.Job]
    private let token = ReverseRenderer.CancelToken()

    private let bar = NSProgressIndicator()
    private let statusLabel = NSTextField(wrappingLabelWithString: "Preparing…")
    private let detailLabel = NSTextField(labelWithString: "")
    /// Set in `loadView`; the only implicitly-unwrapped optionals here
    /// (app/CLAUDE.md allows them for exactly this).
    private var stopButton: NSButton!
    private var closeButton: NSButton!

    private var didStart = false
    private var didFinish = false

    init(document: ProjectDocument, jobs: [ReverseRenderer.Job]) {
        self.document = document
        self.jobs = jobs
        super.init(nibName: nil, bundle: nil)
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("ReverseProgressSheetController does not support NSCoder")
    }

    override func loadView() {
        styleSheetProgressBar(bar)

        styleSheetStatusLabel(statusLabel)
        statusLabel.stringValue =
            jobs.count == 1
            ? "Rendering a reversed copy of “\(jobs[0].name)”…"
            : "Rendering reversed copies of \(jobs.count) files…"

        styleSheetDetailLabel(detailLabel)

        let content = makeProgressStack([bar, statusLabel, detailLabel])

        stopButton = StickerButton(
            title: "Cancel", style: .secondary, target: self, action: #selector(stopClicked(_:)))
        closeButton = StickerButton(
            title: "Close", style: .primary, target: self, action: #selector(closeClicked(_:)))
        hideReturnTarget(closeButton)

        view = makeSheetView(
            title: "Reversing", hint: "AVFoundation cannot play a clip backwards, so Frame Job "
                + "renders the reversed frames once and keeps them in the project package.",
            content: content, buttonRow: makeButtonRow(cancel: stopButton, apply: closeButton))
    }

    /// Reversing a SECOND clip while this sheet is up leaves that one queued
    /// and nothing running — `ensureReversedMedia` refuses to stack sheets. So
    /// the document is asked to look again once this one is off the screen,
    /// which is here rather than in `reverseRenderDidFinish` because a sheet
    /// dismissed a moment ago is still `window.attachedSheet` and the next
    /// presentation would be refused for the same reason. Media the user
    /// stopped or that failed is remembered as refused, so this cannot loop.
    override func viewDidDisappear() {
        super.viewDidDisappear()
        document?.ensureReversedMedia()
    }

    override func viewDidAppear() {
        super.viewDidAppear()
        guard !didStart else { return }
        didStart = true
        let jobs = self.jobs
        let token = self.token
        DispatchQueue.global(qos: .userInitiated).async { [weak self] in
            var rendered: [UInt32] = []
            var failures: [String] = []
            var cancelled = false
            for (index, job) in jobs.enumerated() {
                if token.isCancelled {
                    cancelled = true
                    break
                }
                DispatchQueue.main.async { self?.detailLabel.stringValue = job.name }
                let result = ReverseRenderer(job: job).run(
                    cancel: token,
                    progress: { fraction in
                        let overall = (Double(index) + fraction) / Double(jobs.count)
                        DispatchQueue.main.async { self?.progressed(overall) }
                    })
                switch result {
                case .success:
                    rendered.append(job.media)
                case .failure(let error):
                    if case ReverseRenderer.ReverseError.cancelled = error {
                        cancelled = true
                    } else {
                        failures.append("\(job.name): \(error.localizedDescription)")
                    }
                }
                if cancelled { break }
            }
            let outcome = (rendered: rendered, failures: failures, cancelled: cancelled)
            DispatchQueue.main.async { self?.finished(outcome) }
        }
    }

    private func progressed(_ fraction: Double) {
        guard !didFinish else { return }
        bar.doubleValue = min(max(fraction, 0), 1)
    }

    /// The one exit for all three outcomes. The document is told before
    /// anything is said on screen, because it is what republishes the
    /// resolution and makes the preview stop drawing slates.
    private func finished(
        _ outcome: (rendered: [UInt32], failures: [String], cancelled: Bool)
    ) {
        didFinish = true
        document?.reverseRenderDidFinish(
            rendered: outcome.rendered, failures: outcome.failures, cancelled: outcome.cancelled)
        guard !outcome.failures.isEmpty || outcome.cancelled else {
            // Nothing to report and nothing to decide: the picture is back.
            bar.doubleValue = 1
            dismiss(self)
            return
        }
        statusLabel.textColor = DS.textStrong
        statusLabel.stringValue =
            outcome.cancelled
            ? "Stopped. Clips that are still reversed show a slate until their frames are "
                + "rendered — press Render Reverse in the Timing section of the Clip tab to "
                + "try again."
            : "\(outcome.failures.count) file"
                + "\(outcome.failures.count == 1 ? "" : "s") could not be reversed. Those clips "
                + "show a slate rather than play forwards."
        detailLabel.stringValue = outcome.failures.first ?? ""
        stopButton.isHidden = true
        stopButton.isEnabled = false
        closeButton.isHidden = false
        closeButton.isEnabled = true
    }

    /// Cancelling stops inside the current slice and keeps the files already
    /// finished; the ones left over stay pending, and their clips stay slated.
    @objc private func stopClicked(_ sender: Any?) {
        guard !didFinish else { return }
        stopButton.isEnabled = false
        detailLabel.stringValue = "Stopping…"
        token.cancel()
    }

    @objc private func closeClicked(_ sender: Any?) {
        dismiss(self)
    }
}
import AppKit

/// The document's half of the reverse (spec §11): which reversed clips want a
/// rendered file, the progress sheet that renders them, and the sheet's exit.
///
/// A pure move out of `ProjectDocument.swift` (road map "creator-jobs" CJ0c,
/// T7): the declarations came here whole, in their existing order, with their
/// bodies untouched. **The toll is visibility**: the three stored properties
/// this code reads and writes — `refusedReverseMedia`, `renderingReverseMedia`
/// and `isPresentingReverseSheet` — stay in `ProjectDocument.swift`, because an
/// extension cannot hold a stored property, and are internal rather than
/// private for that reason. `reverseState()` stays `private`: its two callers
/// came with it.
extension ProjectDocument {

    // MARK: - Reverse (spec §11)

    /// Which clips play backwards from a pre-rendered file, which are still
    /// waiting for one, and what would have to be rendered to finish the job.
    ///
    /// Nests are walked as well as the top level: `assign()` gives an inner
    /// media clip its own composition track exactly as a top-level clip gets
    /// one, so an inner reversed clip needs the same substitution — the same
    /// reason `AudioDSPParameters` walks them.
    ///
    /// A media of kind `image` is left alone: a still played backwards is the
    /// same still, so there is nothing to render and nothing to slate.
    private func reverseState() -> (resolution: ReverseResolution, jobs: [ReverseRenderer.Job]) {
        let snapshot = project.snapshot
        var reversed: [(clip: UInt32, media: MediaSnapshot)] = []
        // Built by hand rather than with `uniqueKeysWithValues`, which TRAPS
        // on a repeated key. `validate` rejects duplicate media ids, so this
        // cannot happen — and a project file is still an input, which is the
        // one kind of thing that must never take the app down.
        var media: [UInt32: MediaSnapshot] = [:]
        for entry in snapshot.media where media[entry.id] == nil { media[entry.id] = entry }
        func collect(_ clips: [ClipSnapshot]) {
            for clip in clips where clip.source.isReversed {
                guard let id = clip.source.mediaID, let entry = media[id],
                    entry.kind != .image
                else { continue }
                reversed.append((clip: clip.id, media: entry))
            }
        }
        collect(snapshot.clips)
        for nest in snapshot.nests { collect(nest.clips) }
        guard !reversed.isEmpty, let cache = cacheDirectory else { return (.none, []) }

        var ready: [UInt32: URL] = [:]
        var pending: Set<UInt32> = []
        var jobs: [UInt32: ReverseRenderer.Job] = [:]
        for entry in reversed {
            // A media file that is gone is already a missing clip; there is
            // nothing to reverse and nothing this can add to the slate it
            // already draws.
            guard let source = mediaURL(for: entry.media), entry.media.duration > 0 else {
                continue
            }
            if let url = ReverseCache.existing(
                media: entry.media.id, source: source, in: cache) {
                ready[entry.clip] = url
                continue
            }
            pending.insert(entry.clip)
            guard jobs[entry.media.id] == nil,
                let destination = ReverseCache.destination(
                    media: entry.media.id, source: source, in: cache)
            else { continue }
            jobs[entry.media.id] = ReverseRenderer.Job(
                media: entry.media.id, name: entry.media.name, source: source,
                destination: destination, duration: entry.media.duration, fps: entry.media.fps,
                hasAudio: entry.media.hasAudio)
        }
        return (
            ReverseResolution(ready: ready, pending: pending),
            jobs.values.sorted { $0.media < $1.media }
        )
    }

    /// Tells `CompositionBuilder` — through `ReverseSource`, beside the plan —
    /// which clips read from a reversed file. Main thread, after every edit
    /// and after every render, and before the first composition is built.
    func publishReverseResolution() {
        let state = reverseState()
        // A refusal lasts exactly as long as the clip that earned it. Untick
        // Reverse and the media stops being wanted, so the refusal goes with
        // it — which is what makes ticking the box again a real second ask
        // rather than a silent no.
        refusedReverseMedia.formIntersection(state.jobs.map { $0.media })
        var resolution = state.resolution
        resolution.rampAudio = rampAudioDirectory
        resolution.isolated = isolatedAudioDirectory
        resolution.cache = intendedCacheDirectory
        ReverseSource.shared.publish(resolution, project: project, for: recipeKey)
    }

    /// Renders whatever reversed asset is missing, behind a progress sheet.
    ///
    /// Deliberately quiet about the cases where it should do nothing: a live
    /// gesture (the timeline is moving under the user), a sheet already up
    /// (Export, Consolidate, or this one), and a document with no window
    /// (the agent's, which gets slates and no dialog). It also never retries
    /// media the user has already stopped — see `refusedReverseMedia`.
    ///
    /// Asynchronous on purpose: it is called from inside an edit, and putting
    /// a sheet up while the model is mid-mutation is how re-entrancy bugs
    /// start.
    func ensureReversedMedia() {
        guard !isLiveEditing, !isPresentingReverseSheet else { return }
        let jobs = reverseState().jobs.filter { !refusedReverseMedia.contains($0.media) }
        guard !jobs.isEmpty else { return }
        isPresentingReverseSheet = true
        DispatchQueue.main.async { [weak self] in
            guard let self = self else { return }
            guard let host = self.windowControllers.first?.contentViewController,
                host.view.window?.attachedSheet == nil
            else {
                self.isPresentingReverseSheet = false
                return
            }
            self.renderingReverseMedia = jobs.map { $0.media }
            host.presentAsSheet(
                ReverseProgressSheetController(document: self, jobs: jobs))
        }
    }

    /// Asks for `clip`'s reverse again after a cancel or a failure — the
    /// Clip tab's Timing section's "Render Reverse" button.
    func retryReversedMedia(for clip: ClipSnapshot) {
        guard let media = clip.source.mediaID else { return }
        refusedReverseMedia.remove(media)
        ensureReversedMedia()
    }

    /// What the Clip tab's Timing section's Reverse row should say about one clip.
    func reverseStatus(of clip: ClipSnapshot) -> ReverseStatus {
        guard clip.source.isReversed, let id = clip.source.mediaID,
            let media = project.snapshot.media.first(where: { $0.id == id }),
            media.kind != .image
        else { return .off }
        guard let source = mediaURL(for: media), media.duration > 0 else { return .unavailable }
        guard let cache = cacheDirectory,
            ReverseCache.existing(media: media.id, source: source, in: cache) != nil
        else { return refusedReverseMedia.contains(media.id) ? .stopped : .pending }
        return .ready
    }

    /// The sheet's one exit. Everything here is ordered around one fact: the
    /// files on disk changed, and nothing else in the app can tell.
    func reverseRenderDidFinish(rendered: [UInt32], failures: [String], cancelled: Bool) {
        isPresentingReverseSheet = false
        // Unconditionally, and first: a run that failed or was cancelled may
        // still have created `cache/reversed/` inside the package, and that
        // alone is what makes NSDocument refuse every later save (the trap
        // `packageContentsDidChangeOnDisk` exists for).
        packageContentsDidChangeOnDisk()
        let landed = Set(rendered)
        for media in renderingReverseMedia where !landed.contains(media) {
            refusedReverseMedia.insert(media)
        }
        renderingReverseMedia = []
        publishReverseResolution()
        ensureRampAudio()
        // Not `.projectDocumentDidChange`: the project did not change, the
        // disk did, and the §7.6 rebuild rule compares plans. See the
        // notification's own comment.
        NotificationCenter.default.post(name: .reversedMediaDidChange, object: self)
    }
}
import AppKit

extension ClipPane {
    // MARK: - Timing

    /// Where the clip sits on the ruler, and which way it runs.
    ///
    /// In and Out are the clip's own edges, typed as timecode and committed as
    /// `trim_start` / `trim_end` — the same two ops the edge drags and the two
    /// Trim to Playhead commands use, so a typed edge obeys the same rules.
    ///
    /// **Those rules CLAMP; they do not refuse** (`core/src/edit_clip.rs`, and
    /// the op table in `edit.rs` says so in one line each): `trim_start` pulls
    /// the new start back to the source head and no later than one frame
    /// before the end, `trim_end` pushes the new end to at least one frame of
    /// clip and no further than the source has left. **The core declines** —
    /// both arms beep from `applyEdit` and neither makes an undo step — when
    /// the clamped edge is where the edge already was or the two clamps cross
    /// (an IDENTITY: a clamp landing where the clip already is names no rule),
    /// and when the move breaks the overlap rule (a REFUSAL, in that rule's
    /// own sentence). So a typed value out of range does not beep: it lands
    /// clamped, and the field re-reads what the core committed. Nothing here
    /// clamps on the user's behalf, which keeps that one rule in one place.
    ///
    /// Duration is read-only because it has no op of its own: it is
    /// `end − start`, and §6 gives you the two edges instead.
    ///
    /// In, Out and Duration are one clip only. Two clips have two In points,
    /// and a field showing the first one's while writing to both would be a
    /// lie about what it edits — `reverseTimingSection()` is what a
    /// multi-clip selection gets instead.
    ///
    /// **It binds by clip ID, captured here, and reads fresh through it** —
    /// the rule every other by-id row in this panel follows
    /// (`VideoPane.transitionSection`, `DocumentPane.markerRow`), and the one
    /// place in the inspector where breaking it edits the WRONG CLIP rather
    /// than merely showing a stale number. These two fields commit on blur,
    /// and a blur can be caused by the rebuild itself: `rebuild()` removes
    /// every arranged subview, removing a field that is being typed into ends
    /// its editing session, and only then does `controlTextDidEndEditing`
    /// fire. Clicking another clip in the timeline takes that path — the
    /// timeline's content view refuses first responder, so the field keeps it
    /// while the selection changes underneath — and a `binding.primary` read
    /// inside the write closure would by then name the clip that was just
    /// clicked. `binding.snapshot.clip(id)` names the one the user typed into.
    /// Once that clip is GONE the reads fall back — 0 for the two edges, "—"
    /// for the duration — and a write still names the dead id, which the core
    /// rejects by name and `applyEdit` puts up as its message. That is loud
    /// for something rare (the clip has to be deleted while its field holds
    /// the field editor) but it is honest, and it is not the thing this rule
    /// exists to prevent, which is editing whichever clip was clicked next.
    ///
    /// The Reverse group under the edges is `reverseRows(over:mixed:)`, shared
    /// with the multi-clip section below.
    func timingSection(_ id: UInt32) -> InspectorSection {
        let binding = self.binding
        /// Read fresh on every call through the captured id, never captured
        /// itself: a trim REPLACES the clip snapshot, and the row is refreshed
        /// rather than rebuilt.
        func clip() -> ClipSnapshot? { binding.snapshot.clip(id) }
        func fps() -> Fps { binding.canvas.fps }
        func frames() -> Bool { binding.canvas.timecodeFrames }
        func duration() -> String {
            guard let clip = clip() else { return "—" }
            return ReelTime.format(clip.duration, fps: fps(), frames: frames())
        }
        let start = InspectorTimecodeField(
            read: { clip()?.start ?? 0 },
            write: { value in
                binding.apply("Trim Start", [.trimStart(clip: id, to: value)])
            },
            fps: fps, frames: frames,
            onEdit: { binding.edited() })
        start.toolTip = "Where the clip starts — trims its front edge"
        let end = InspectorTimecodeField(
            read: { clip()?.end ?? 0 },
            write: { value in
                binding.apply("Trim End", [.trimEnd(clip: id, to: value)])
            },
            fps: fps, frames: frames,
            onEdit: { binding.edited() })
        end.toolTip = "Where the clip ends — trims its back edge"

        var rows: [NSView] = [
            inspectorRow("In", [start]),
            inspectorRow("Out", [end]),
            inspectorRow("Duration", [inspectorReadout { duration() }]),
        ]
        // Reverse is a media-source op (`set_reversed`, §6); a text or shape
        // clip has no frames to turn around. The clip is re-filtered rather
        // than assumed because `allMedia` answered at BUILD time and the rows
        // read live: an empty list is no ops, which is a beep from `apply` and
        // the right answer for a clip that is no longer there. No mixed badge:
        // one clip cannot disagree with itself.
        if videoPane.allMedia {
            rows.append(
                contentsOf: reverseRows(
                    over: {
                        guard let clip = clip(), clip.source.hasSourceBound else { return [] }
                        return [clip]
                    },
                    mixed: nil))
        }
        return InspectorSection(
            id: "clip.timing", title: "Timing",
            summary: { duration() },
            defaultExpanded: false,
            rows: rows)
    }

    /// Timing for a MULTI-clip media selection: the Reverse group, and nothing
    /// else, because In, Out and Duration each describe one edge of one clip.
    ///
    /// The same section id as the single-clip Timing, so the group the user
    /// opened stays open as the selection grows and shrinks, and the same
    /// summary in the header's own vocabulary — the total of what is selected,
    /// spelled the way `ClipSelectionHeaderView` spells it.
    func reverseTimingSection() -> InspectorSection {
        let binding = self.binding
        /// Live, not captured: the rows survive a refresh, and `allMedia`
        /// answered for the selection this build saw.
        func clips() -> [ClipSnapshot] { binding.clips.filter { $0.source.hasSourceBound } }
        func total() -> String {
            let sum = clips().reduce(Ticks(0)) { $0 + $1.duration }
            let canvas = binding.canvas
            return ReelTime.format(sum, fps: canvas.fps, frames: canvas.timecodeFrames) + " total"
        }
        return InspectorSection(
            id: "clip.timing", title: "Timing",
            summary: { total() },
            defaultExpanded: false,
            rows: reverseRows(
                over: clips,
                mixed: { binding.mixed(clips()) { $0.source.isReversed } }))
    }

    /// The Reverse group — the box, the state readout and the retry button —
    /// over whatever clips the section speaks for: the one clip of a
    /// single-clip Timing, every media clip of a multi-clip one. One op per
    /// clip, all in one `apply`, so the fan-out is a single undo step.
    ///
    /// **Reverse carries a state readout that no other control here needs.**
    /// AVFoundation cannot play a clip backwards, so ticking the box does not
    /// change the picture by itself: it makes the app pre-render the frames
    /// (spec §11), and until they exist the clip draws a slate rather than
    /// lying about which way it is going. The readout says which of those the
    /// clip is in, and the button is what restarts a render the user stopped —
    /// the one path back from `ReverseStatus.stopped`, since nothing retries
    /// on its own.
    func reverseRows(
        over clips: @escaping () -> [ClipSnapshot], mixed: (() -> Bool)?
    ) -> [NSView] {
        let binding = self.binding
        /// One line for what may be several clips. Stopped outranks pending
        /// deliberately: it is the state with something to do about it, and a
        /// "Rendering…" that hid a stopped clip behind a rendering one would
        /// grey out the only button that could fix it.
        func status() -> ReverseStatus {
            guard let document = binding.document else { return .off }
            let states = clips().map { document.reverseStatus(of: $0) }
            for state in [ReverseStatus.stopped, .pending, .unavailable, .ready]
            where states.contains(state) {
                return state
            }
            return .off
        }
        let render = OptionButtonControl(
            title: "Render Reverse",
            action: {
                guard let document = binding.document else { return }
                guard let next = clips().first(where: {
                    document.reverseStatus(of: $0) == .stopped
                })
                else { return }
                // **Pitfall:** one press starts ONE media.
                // `ensureReversedMedia` refuses to open a second sheet while
                // one is up, so un-refusing every stopped clip here would
                // leave all but the first reading "Rendering…" with nothing
                // rendering. Retried one at a time, the readout keeps saying
                // "Not rendered" while any remain, and the next press takes
                // the next one.
                document.retryReversedMedia(for: next)
            },
            enabled: { status() == .stopped },
            onEdit: {})
        render.toolTip = "Render the reversed frames these clips need"
        return [
            inspectorCheckRow(
                "Reverse", binding, name: "Reverse",
                read: { clips().first?.source.isReversed ?? false },
                ops: { value in
                    clips().map { ReelOp.setReversed(clip: $0.id, reversed: value) }
                },
                mixed: mixed, resets: false),
            inspectorRow("Reversed frames", [inspectorReadout { status().summary }]),
            inspectorButtonRow([render]),
        ]
    }
}

