    static func jobs(
        for clips: [ClipSnapshot], in snapshot: ProjectSnapshot, urls: [UInt32: URL]
    ) -> (jobs: [Job], problems: [CaptionLayout.Problem]) {
        jobs(for: clips, in: snapshot, urls: urls, maps: { _ in nil })
    }

